INSERT INTO public.source (id, title, source_type, author, edition, url, note)
SELECT id, title, source_type, author, edition, url, note FROM jsonb_populate_recordset(NULL::public.source, '[{"title": "旧五代史·卷101·隐帝本纪·乾祐元年十二月", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/b8ce7838037279cfbdd88a95bcd6fb9f26236396/content/books/zizhi-tongjian/vol-288/year-0948/part-09/sources/library/jiuwudaishi-101-december-948/source.txt", "note": "《旧五代史》卷101·隐帝本纪·乾祐元年十二月，段落 jiu-wudaishi-205deb4a7860-p002462；已核上下文及传主，纸本及异文待核。", "id": "931e2b3e-52d4-50a6-b465-da07f4acc580"}, {"title": "旧五代史·卷107·史弘肇传·刑杀与军狱", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/b8ce7838037279cfbdd88a95bcd6fb9f26236396/content/books/zizhi-tongjian/vol-288/year-0948/part-09/sources/library/jiuwudaishi-107-shi-punishments/source.txt", "note": "《旧五代史》卷107·史弘肇传·刑杀与军狱，段落 jiu-wudaishi-205deb4a7860-p002555；已核上下文及传主，纸本及异文待核。", "id": "38061fa7-243a-5f22-8624-a0d83925de8f"}, {"title": "旧五代史·卷107·史弘肇传·杨乙征钱", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/b8ce7838037279cfbdd88a95bcd6fb9f26236396/content/books/zizhi-tongjian/vol-288/year-0948/part-09/sources/library/jiuwudaishi-107-yang-yi-collections/source.txt", "note": "《旧五代史》卷107·史弘肇传·杨乙征钱，段落 jiu-wudaishi-205deb4a7860-p002556；已核上下文及传主，纸本及异文待核。", "id": "52ffe01d-060e-5ba9-9ed4-fb8170695c76"}, {"title": "宋史·卷265·李昉传·籍贯与早年任职", "source_type": "primary", "author": "脱脱等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/b8ce7838037279cfbdd88a95bcd6fb9f26236396/content/books/zizhi-tongjian/vol-288/year-0948/part-09/sources/library/songshi-265-li-fang-origin/source.txt", "note": "《宋史》卷265·李昉传·籍贯与早年任职，段落 songshi-9c6e46fee832-p058423；已核上下文及传主，纸本及异文待核。", "id": "f2583666-27d6-5fbc-8b2c-577cf8baa92b"}, {"title": "宋史·卷269·陶谷传·姓氏与籍贯", "source_type": "primary", "author": "脱脱等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/b8ce7838037279cfbdd88a95bcd6fb9f26236396/content/books/zizhi-tongjian/vol-288/year-0948/part-09/sources/library/songshi-269-tao-gu-origin/source.txt", "note": "《宋史》卷269·陶谷传·姓氏与籍贯，段落 songshi-9c6e46fee832-p058767；已核上下文及传主，纸本及异文待核。", "id": "e0b59114-65de-5b58-9298-28c66e55a588"}, {"title": "资治通鉴·卷288·乾祐元年·李崧案", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/b8ce7838037279cfbdd88a95bcd6fb9f26236396/content/books/zizhi-tongjian/vol-288/year-0948/part-09/sources/library/tongjian-288-948-li-song-case/source.txt", "note": "《资治通鉴》卷288·乾祐元年·李崧案，段落 zizhi-tongjian-a63549944a71-p003420；已核上下文及传主，纸本及异文待核。", "id": "15490a22-9491-51f1-a3bd-8b639ffc682c"}, {"title": "资治通鉴·卷288·乾祐元年·年末记载", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/b8ce7838037279cfbdd88a95bcd6fb9f26236396/content/books/zizhi-tongjian/vol-288/year-0948/part-09/sources/library/tongjian-288-948-year-end/source.txt", "note": "《资治通鉴》卷288·乾祐元年·年末记载，段落 zizhi-tongjian-a63549944a71-p003421；已核上下文及传主，纸本及异文待核。", "id": "344f2a55-f39d-53b3-b041-6bf44314b17a"}, {"title": "新五代史·卷10·汉本纪·乾祐元年", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/b8ce7838037279cfbdd88a95bcd6fb9f26236396/content/books/zizhi-tongjian/vol-288/year-0948/part-09/sources/library/xinwudaishi-010-li-song-burial/source.txt", "note": "《新五代史》卷10·汉本纪·乾祐元年，段落 xin-wudaishi-b08f244b9241-p000351；已核上下文及传主，纸本及异文待核。", "id": "6d0ed8c6-6c88-592f-874c-20398cedfcf8"}, {"title": "新五代史·卷62·南唐世家·援救李守贞", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/b8ce7838037279cfbdd88a95bcd6fb9f26236396/content/books/zizhi-tongjian/vol-288/year-0948/part-09/sources/library/xinwudaishi-062-li-jinquan-relief/source.txt", "note": "《新五代史》卷62·南唐世家·援救李守贞，段落 xin-wudaishi-b08f244b9241-p003144；已核上下文及传主，纸本及异文待核。", "id": "702ba836-b926-5077-b82e-129f6105f39a"}, {"title": "新五代史·卷65·南汉世家·贺州陷阱", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/b8ce7838037279cfbdd88a95bcd6fb9f26236396/content/books/zizhi-tongjian/vol-288/year-0948/part-09/sources/library/xinwudaishi-065-hezhou-traps/source.txt", "note": "《新五代史》卷65·南汉世家·贺州陷阱，段落 xin-wudaishi-b08f244b9241-p003285；已核上下文及传主，纸本及异文待核。", "id": "47327e81-2499-50f5-a4a8-da4df94cd561"}, {"title": "旧五代史·卷一百〇一", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/a2b6b6c94d54b9864bcd3d22174bace805c3e93e/content/books/zizhi-tongjian/vol-288/year-0948/part-08/sources/library/jiuwudaishi-101-november-948/source.txt", "note": "《旧五代史》卷一百〇一，段落 jiu-wudaishi-205deb4a7860-p002461；EPUB电子本，纸本及异文待核", "id": "a3ad3d6a-7b41-5245-a428-60d4362aa49d"}, {"title": "旧五代史·卷一百〇八", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/a2b6b6c94d54b9864bcd3d22174bace805c3e93e/content/books/zizhi-tongjian/vol-288/year-0948/part-08/sources/library/jiuwudaishi-108-li-song-estate/source.txt", "note": "《旧五代史》卷一百〇八，段落 jiu-wudaishi-205deb4a7860-p002588；EPUB电子本，纸本及异文待核", "id": "5b02a7fc-c9dd-5907-8cfc-e1c81f8d9a36"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "史弘肇", "aliases": ["史宏肇"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "荥泽人，947年二月任刘知远的武节都指挥使，奉命在球场集合各军，宣布出兵日期。《旧五代史》亦有史宏肇的字形。生卒年暂未录入。", "biography": null, "status": "draft", "id": "c36d0d69-d2db-5ee8-9bf6-80791eb21dda"}, {"name": "解晖", "aliases": ["解暉"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后汉军司孔目官。史书记载，史弘肇信任他，他在军狱中滥用酷刑，逼受审者作虚假供述。生卒年尚未确定。", "biography": null, "status": "draft", "id": "ae0decd0-db0d-525d-baf6-f776759f31ef"}, {"name": "葛延遇", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "李屿的仆人，替李屿经营贩卖事务。948年与苏逢吉的仆人李澄合谋告发李屿谋反，李崧家族随后遭到诛杀。史书将此案记为冤案。生卒年尚未确定。", "biography": null, "status": "draft", "id": "811202de-9a8a-5ae0-b002-11da91b78d08"}, {"name": "李屿", "aliases": ["李嶼"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "李崧的弟弟，后汉朝官。李崧旧宅被苏逢吉占有后，李屿与李崧的另一位弟弟李㠖饮酒时曾表达怨言，苏逢吉因此对李崧一方生怨。生卒年及具体官职尚未录入。", "biography": null, "status": "draft", "id": "3c5f9b7a-188d-5885-adb8-894048d9374b"}, {"name": "李澄", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "苏逢吉的仆人。948年与葛延遇合谋告发李屿谋反，史书记载二人因此获赏，并将李崧家族遭诛记为冤案。生卒年尚未确定。", "biography": null, "status": "draft", "id": "c22adf9e-4986-598b-97e9-e91da5e89ee1"}, {"name": "苏逢吉", "aliases": ["蘇逢吉"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "长安人，任河东节度判官。947年刘知远任命他为中书侍郎、同平章事。具体生卒年尚未录入。", "biography": null, "status": "draft", "id": "1136d429-42fd-5166-94a0-f2dd9af9c920"}, {"name": "李崧", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷274同光四年条所见人物：李崧。", "biography": null, "status": "draft", "id": "42727c37-29c7-534f-b0f7-900992c16def"}, {"name": "李㠖", "aliases": ["李嶬"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "李崧的弟弟，后汉朝官，与李屿饮酒时曾对家产被占表达怨言。《旧五代史》同段记㠖，本纪另写嶬；《通鉴》电子底本用山、义的组合占位表示名字。生卒年及具体官职尚未录入。", "biography": null, "status": "draft", "id": "a55e6acb-2f09-5fda-96df-e4a0f280616a"}, {"name": "王凝（李屿外甥）", "aliases": ["王凝"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "李崧案供述中被提及的人物，称为李屿的外甥。供述被《资治通鉴》记为李屿受逼自诬，不能据此认定王凝确曾谋反。与晚唐其他同名人物的联系尚未确认，单独建档。生卒年未载。", "biography": null, "status": "draft", "id": "7119810e-5b77-51d7-8b6c-a988e30985fd"}, {"name": "李守贞", "aliases": ["李守貞"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋内客省使。940年五月受命担任马全节讨伐李金全军队的都监，职务由《旧五代史》本纪补充。生卒年未据本段确定。", "biography": null, "status": "draft", "id": "a3d16959-684f-5c82-b848-8dcbdc73e85a"}, {"name": "刘承祐", "aliases": ["劉承祐", "后汉隐帝"], "era": "五代十国", "birth_year": 931, "death_year": null, "description": "刘知远第二子，母亲为李氏。《旧五代史》记他生于931年三月七日的邺都旧宅，曾任左卫大将军和大内都点检。948年二月先封周王，随后依据公布的遗制继承后汉皇位。《资治通鉴》记其即位时十八岁。", "biography": null, "status": "draft", "id": "96b54cac-772d-54e8-b2de-975b3be49e85"}, {"name": "李昉", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后汉秘书郎，李崧的族侄。李崧案后拜访陶谷，听陶谷自称在此案中出了力而惊惧。《资治通鉴》称真定李昉，《宋史》记深州饶阳人、字明远，籍贯写法分别保留。生卒年尚未录入。", "biography": null, "status": "draft", "id": "7a1adcce-f1e0-5503-b71e-c347a33c346f"}, {"name": "陶谷", "aliases": ["陶穀"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后汉翰林学士，曾受李崧引荐。《资治通鉴》在李崧遭苏逢吉排挤的背景中记陶谷也加入诬陷。姓名谷、穀按繁简匹配，生卒年尚未录入。", "biography": null, "status": "draft", "id": "7d8e6fa9-c77d-5157-b782-a59c82d864be"}, {"name": "杨乙", "aliases": ["楊乙"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "史弘肇的亲信属吏，受命征收归德军府收入。史书记载他仗势骄横，每月征钱一万缗交给史弘肇，当地民众深受其害。生卒年未载。", "biography": null, "status": "draft", "id": "9df509c0-8b83-58f9-8b58-c1a3572a6c05"}, {"name": "舒元", "aliases": ["朱元", "硃元"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "沈丘人，早先以游士身份投靠李守贞。李守贞被后汉围攻后，让他改姓朱，赴南唐求援。《新五代史》记求援者为朱元。生卒年尚未确定。", "biography": null, "status": "draft", "id": "4747ce90-dd4b-5e0b-a0c8-7420788a2347"}, {"name": "杨讷", "aliases": ["楊訥", "李平"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "嵩山道士，早先以游士身份投靠李守贞。李守贞被后汉围攻后，让他改姓李、名平，与舒元通过隐秘道路到南唐求援。生卒年未载。", "biography": null, "status": "draft", "id": "2e43b907-5e6b-52bd-8ad9-35801725e3b9"}, {"name": "查文徽", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "休宁人，南唐官员。943年李璟即位后，史书记他与陈觉、冯延巳、冯延鲁、魏岑互相引荐，不久与魏岑同任枢密副使。当时五人被称为五鬼，称呼按史书记载保留。生卒年尚未核。", "biography": null, "status": "draft", "id": "b0abcb8a-3aa7-5d58-8f3c-79f4fc15b117"}, {"name": "魏岑", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南唐齐王府僚属。李昪在位时，常梦锡曾反对他与陈觉、冯延巳等陪侍李璟。生卒年尚未核。", "biography": null, "status": "draft", "id": "58f25557-fd68-5851-90ad-b847734e7dfe"}, {"name": "李璟", "aliases": ["徐景通", "景通", "李景"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷272同光元年条所见人物：李璟。", "biography": null, "status": "draft", "id": "6bf72971-88c3-5187-8f25-98cde2a9554a"}, {"name": "李金全", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：李金全，前节度使、多次献马者。", "biography": null, "status": "draft", "id": "13205047-3c88-59d8-9900-ef435bd6e59a"}, {"name": "刘彦贞", "aliases": ["劉彥貞"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "刘信之子，南唐楚州刺史。944年条下追述他改任濠州观察使，迅速前往替代刘崇俊。具体任职年月与生卒年未载。", "biography": null, "status": "draft", "id": "3a86e5c0-cc8e-5120-888d-a75e599e8e30"}, {"name": "刘知远", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷271贞明五年条所见人物：刘知远。", "biography": null, "status": "draft", "id": "69fa3b4b-2f0d-5799-bbf5-e378af9816e1"}, {"name": "高保融", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "高从诲之子，荆南节度副使。948年十月父亲病重时，受命管理内外兵马事务；高从诲去世后，以留后身份暂掌军府。《新五代史》记他是高从诲的第三子。生卒年尚未确定。", "biography": null, "status": "draft", "id": "88e76c46-c48c-5103-9a49-99e0b54eed61"}, {"name": "刘弘熙", "aliases": ["劉弘熙", "刘洪熙", "劉洪熙"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：刘弘熙，获封王爵之子。", "biography": null, "status": "draft", "id": "b67079e8-6ec8-5150-9451-5b3ce7983fec"}, {"name": "吴怀恩", "aliases": ["吳懷恩"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "番禺人，南汉内常侍。刘弘度即位后，他与越王刘弘昌多次劝谏，刘弘度没有听从。具体劝谏年月和生卒年未载。", "biography": null, "status": "draft", "id": "10645068-7e2a-59d2-8714-eb605c240fb1"}, {"name": "马希广", "aliases": ["馬希廣", "德丕"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：马希广，武安节度副使，临时领府者。", "biography": null, "status": "draft", "id": "eb8e4d76-8384-56ed-a225-77675cfd8927"}, {"name": "徐知新", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": 948, "description": "楚国决胜指挥使。948年十二月奉马希广之命率军救援贺州，救兵在攻城时落入南汉军设置的陷阱，败退后被马希广处死。其他经历尚未确定。", "biography": null, "status": "draft", "id": "e461df45-5921-59a6-8619-ed29d0fb03d1"}, {"name": "吴珣", "aliases": ["吳珣"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南汉巨象指挥使。《新五代史》记他与吴怀恩攻克贺州，并在城下设置陷阱，击败赶来救援的楚军。生卒年尚未确定。", "biography": null, "status": "draft", "id": "b5faad77-eee9-5173-8af3-c7cdb687ef87"}, {"name": "王景崇", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋官员。937年担任引进使，受命劝秘琼接受任命。史书记载他是邢州人。", "biography": null, "status": "draft", "id": "5f673eda-0daa-5174-926f-dca3e0982614"}, {"name": "孟昶", "aliases": ["孟仁赞", "孟仁贊"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷275天成二年条所见人物：孟昶，孟子、被迎者。", "biography": null, "status": "draft", "id": "666201f7-9186-590e-8d5b-2a4a605dba69"}, {"name": "安思谦", "aliases": ["安思謙"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：安思谦，茶酒库使、曾事藩邸者。", "biography": null, "status": "draft", "id": "6ec752d6-91f9-5760-8ea8-c552e6369345"}, {"name": "高彦俦", "aliases": ["高彥儔"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：高彦俦，太原人、昭武都监、拟领兵者。", "biography": null, "status": "draft", "id": "b335c31e-ee43-595d-8eb5-e601824ba527"}, {"name": "申贵", "aliases": ["申貴"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "潞州人，后蜀眉州刺史。948年十月奉安思谦命率二千兵前往模壁，在竹林设伏；丁酉早晨用数百兵在宝鸡前列阵，引诱后汉兵追击。后汉兵中伏败退，蜀军追击并攻破宝鸡寨。生卒年未载。", "biography": null, "status": "draft", "id": "0a0e0938-9bfd-5f40-a478-e6c2b3eead34"}, {"name": "韩保贞", "aliases": ["韓保貞"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：韩保贞，丰德库使、曾事藩邸者。", "biography": null, "status": "draft", "id": "7090cd80-1efa-59ab-9b8f-05f88da57d52"}, {"name": "赵晖", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷257光启三年条所见人物：赵晖。", "biography": null, "status": "draft", "id": "9efd6fe6-4ba6-5e2b-99cc-751822d75039"}, {"name": "郭威", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷272同光元年条所见人物：郭威。", "biography": null, "status": "draft", "id": "3fe84db3-aa25-5be9-9dd3-8b46e28213af"}, {"name": "周光逊", "aliases": ["周光遜"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "李守贞的副使。948年十二月在河中与王继勋、聂知遇守城西。生卒年尚未确定。", "biography": null, "status": "draft", "id": "03d0befb-90fd-54e1-a23a-929e067d849d"}, {"name": "王继勋（李守贞将）", "aliases": ["王继勋（平陆将领）"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "平陆人，李守贞部将。948年李守贞自称秦王后，派他率兵占据潼关。与闽国王氏宗族成员和宋代同名人物分开，未作无证合并。生卒年未载。", "biography": null, "status": "draft", "id": "cebf1403-38a6-5f4e-b202-577b1ed71892"}, {"name": "聂知遇", "aliases": ["聶知遇"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "李守贞的裨将。948年十二月与周光逊、王继勋守河中城西。生卒年未载。", "biography": null, "status": "draft", "id": "93911802-b076-5027-80b6-c447c4fb93a7"}, {"name": "白文珂", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋代州刺史。944年九月在七里烽击败契丹；新史记丙子，旧史壬辰记录太原奏报。生卒年本次引文未载。", "biography": null, "status": "draft", "id": "4144a98b-cc52-5b8e-afec-6ad9ed55b845"}, {"name": "刘词", "aliases": ["劉詞"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋奉国都指挥使，元城人。942年与王清率军先登襄州。生卒年未载。", "biography": null, "status": "draft", "id": "1d26caf6-67d4-52b5-a6df-b9dff192cea5"}, {"name": "徐光溥", "aliases": ["徐光溥（后蜀官员）"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后蜀官员。948年由翰林学士、兵部侍郎任中书侍郎兼礼部尚书，与李昊一同加同平章事。生卒年未据本段确定。", "biography": null, "status": "draft", "id": "6d13e792-75d4-5b0e-a25d-12e4b92f9796"}, {"name": "安康长公主", "aliases": ["安康長公主"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "前蜀长公主，姓名和具体亲属关系尚未据当前史料确定。948年十二月，徐光溥因用艳辞挑逗她而被罢去宰相职务。", "biography": null, "status": "draft", "id": "417136f3-e146-5397-b641-075800b329b1"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

