SELECT id, subject_table, subject_id, field_path, claim_text, source_id, citation, note, status FROM jsonb_populate_recordset(NULL::public.fact_claim, '[{"subject_table": "event", "field_path": "description", "claim_text": "史弘肇任用解晖，军狱受审者被逼作虚假供述。", "citation": "卷288·乾祐元年（948年十一月至十二月及追述）·zztj-v288-y0948-p059·原文件第65行", "note": "原文：汉法既严，而侍卫都指挥使史弘肇尤残忍，宠任孔目官解晖，凡入军狱者，使之随意锻炼，无不自诬。；核对说明：锻炼指罗织罪状及刑讯，不按现代训练解释；自诬是被逼承认虚假罪名，不据供词认定受审者确实犯罪。", "status": "draft", "id": "043011de-9631-5d17-8262-e142be137c29", "subject_id": "b84fbcc8-ea82-5156-a446-6a347414255d", "source_id": "15490a22-9491-51f1-a3bd-8b639ffc682c"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "后汉初年史弘肇掌禁军期间的追叙，具体年月未载", "citation": "卷288·乾祐元年（948年十一月至十二月及追述）·zztj-v288-y0948-p059·原文件第65行", "note": "原文：汉法既严，而侍卫都指挥使史弘肇尤残忍，宠任孔目官解晖，凡入军狱者，使之随意锻炼，无不自诬。；核对说明：按《资治通鉴》及对应补证纪时；追叙或他书记载另作说明，不自行换算公历日期。", "status": "draft", "id": "3c84ad4c-ef4a-5616-ac1c-edc80347f96e", "subject_id": "b84fbcc8-ea82-5156-a446-6a347414255d", "source_id": "15490a22-9491-51f1-a3bd-8b639ffc682c"}, {"subject_table": "person", "field_path": "description", "claim_text": "史弘肇：信任孔目官解晖，任其在军狱中审讯。", "citation": "卷288·乾祐元年（948年十一月至十二月及追述）·zztj-v288-y0948-p059·原文件第65行", "note": "原文：汉法既严，而侍卫都指挥使史弘肇尤残忍，宠任孔目官解晖，凡入军狱者，使之随意锻炼，无不自诬。；核对说明：核对同名、职务及行动后识别主体；展示简体，摘录保留原字。", "status": "draft", "id": "53d3f232-f831-5c01-9ed4-6c4ab6924698", "subject_id": "c36d0d69-d2db-5ee8-9bf6-80791eb21dda", "source_id": "15490a22-9491-51f1-a3bd-8b639ffc682c"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "史弘肇：信任孔目官解晖，任其在军狱中审讯。", "citation": "卷288·乾祐元年（948年十一月至十二月及追述）·zztj-v288-y0948-p059·原文件第65行", "note": "原文：汉法既严，而侍卫都指挥使史弘肇尤残忍，宠任孔目官解晖，凡入军狱者，使之随意锻炼，无不自诬。；核对说明：参与身份依据本句；人名沿用已有主体，原文不改字。", "status": "draft", "id": "677914a6-bb0c-54cf-b1f4-e4a58de3eb56", "subject_id": "28c1442f-fe76-5e46-85b3-ef8f7001e5d8", "source_id": "15490a22-9491-51f1-a3bd-8b639ffc682c"}, {"subject_table": "person", "field_path": "description", "claim_text": "解晖：滥用刑讯，逼受审者作虚假供述。", "citation": "卷288·乾祐元年（948年十一月至十二月及追述）·zztj-v288-y0948-p059·原文件第65行", "note": "原文：汉法既严，而侍卫都指挥使史弘肇尤残忍，宠任孔目官解晖，凡入军狱者，使之随意锻炼，无不自诬。；核对说明：核对同名、职务及行动后识别主体；展示简体，摘录保留原字。", "status": "draft", "id": "93d30ae5-680d-5d6e-a55d-b8af8a82b2ec", "subject_id": "ae0decd0-db0d-525d-baf6-f776759f31ef", "source_id": "15490a22-9491-51f1-a3bd-8b639ffc682c"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "解晖：滥用刑讯，逼受审者作虚假供述。", "citation": "卷288·乾祐元年（948年十一月至十二月及追述）·zztj-v288-y0948-p059·原文件第65行", "note": "原文：汉法既严，而侍卫都指挥使史弘肇尤残忍，宠任孔目官解晖，凡入军狱者，使之随意锻炼，无不自诬。；核对说明：参与身份依据本句；人名沿用已有主体，原文不改字。", "status": "draft", "id": "56455ab9-86aa-5a4c-b193-c14b8eea3124", "subject_id": "243480aa-c375-5f26-9a96-f873e3608002", "source_id": "15490a22-9491-51f1-a3bd-8b639ffc682c"}, {"subject_table": "event", "field_path": "description", "claim_text": "《旧五代史》也记解晖任军司孔目吏，在军狱中酷刑审讯，受审者作虚假供述。", "citation": "《旧五代史》卷107·史弘肇传·刑杀与军狱，段落 jiu-wudaishi-205deb4a7860-p002555；已核上下文及传主，纸本及异文待核。", "note": "原文：軍司孔目吏解暉，性狡而酷，凡有推劾，隨意鍛煉。人有抵軍禁者，被其苦楚，無不自誣以求死所，都人遇之，莫敢仰視。；核对说明：这是对军狱审讯方式的补证；后文何福殷案不因此提前并入李崧案。", "status": "draft", "id": "8ee777f7-2634-54bd-8588-2fda907ee770", "subject_id": "b84fbcc8-ea82-5156-a446-6a347414255d", "source_id": "38061fa7-243a-5f22-8624-a0d83925de8f"}, {"subject_table": "event", "field_path": "description", "claim_text": "三处叛乱使人心不安，京城出现惊扰民众的谣言。", "citation": "卷288·乾祐元年（948年十一月至十二月及追述）·zztj-v288-y0948-p059·原文件第65行", "note": "原文：及三叛连兵，群情震动，民间或讹言相惊骇。；核对说明：三叛承此前河中、永兴、凤翔；史书没有列出谣言内容，不新造消息。", "status": "draft", "id": "69f417c3-ead4-5508-8d1a-e700c479a35f", "subject_id": "c1892469-cc4a-500a-b9e4-0e28b669de89", "source_id": "15490a22-9491-51f1-a3bd-8b639ffc682c"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "948年河中、永兴、凤翔叛乱期间，具体日未载", "citation": "卷288·乾祐元年（948年十一月至十二月及追述）·zztj-v288-y0948-p059·原文件第65行", "note": "原文：及三叛连兵，群情震动，民间或讹言相惊骇。；核对说明：按《资治通鉴》及对应补证纪时；追叙或他书记载另作说明，不自行换算公历日期。", "status": "draft", "id": "26ea1706-e30f-51db-86c5-2f61d6f83d4f", "subject_id": "c1892469-cc4a-500a-b9e4-0e28b669de89", "source_id": "15490a22-9491-51f1-a3bd-8b639ffc682c"}, {"subject_table": "event", "field_path": "description", "claim_text": "史弘肇掌禁军巡逻京城，抓到被指为犯罪的人后，不按罪情轻重和法律规定处置，擅自杀人，或施加残酷刑罚。史书记载，虽盗贼减少，冤死者很多，却无人敢申辩。", "citation": "卷288·乾祐元年（948年十一月至十二月及追述）·zztj-v288-y0948-p059·原文件第65行", "note": "原文：弘肇掌部禁兵，巡逻京城，得罪人，不问情轻重，于法何如，皆专杀不请。或决口断舌，斫筋，折胫，无虚日。虽奸盗屏迹，而冤死者甚众，莫敢辨诉。；核对说明：把盗贼减少与冤死者多同时记录；不把每个被捕者都认作已查明犯罪，也不补死亡人数。", "status": "draft", "id": "4e2336d8-abeb-5a1d-8bc9-fd8f4142b7df", "subject_id": "a4a43459-e1f4-54f7-bb2e-e101fbe00008", "source_id": "15490a22-9491-51f1-a3bd-8b639ffc682c"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "948年三处叛乱期间，具体日未载", "citation": "卷288·乾祐元年（948年十一月至十二月及追述）·zztj-v288-y0948-p059·原文件第65行", "note": "原文：弘肇掌部禁兵，巡逻京城，得罪人，不问情轻重，于法何如，皆专杀不请。或决口断舌，斫筋，折胫，无虚日。虽奸盗屏迹，而冤死者甚众，莫敢辨诉。；核对说明：按《资治通鉴》及对应补证纪时；追叙或他书记载另作说明，不自行换算公历日期。", "status": "draft", "id": "ebb53d06-7852-5233-9455-e5100f043e17", "subject_id": "a4a43459-e1f4-54f7-bb2e-e101fbe00008", "source_id": "15490a22-9491-51f1-a3bd-8b639ffc682c"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "史弘肇：掌禁军巡逻京城，不按罪情轻重擅自施刑杀人。", "citation": "卷288·乾祐元年（948年十一月至十二月及追述）·zztj-v288-y0948-p059·原文件第65行", "note": "原文：弘肇掌部禁兵，巡逻京城，得罪人，不问情轻重，于法何如，皆专杀不请。或决口断舌，斫筋，折胫，无虚日。虽奸盗屏迹，而冤死者甚众，莫敢辨诉。；核对说明：参与身份依据本句；人名沿用已有主体，原文不改字。", "status": "draft", "id": "ef450513-7c99-55d5-9d5d-208613f962e5", "subject_id": "01c708d6-853e-5d1c-b633-ecb213bd533a", "source_id": "15490a22-9491-51f1-a3bd-8b639ffc682c"}, {"subject_table": "event", "field_path": "description", "claim_text": "《旧五代史》也记史弘肇不问罪情轻重，听说有人犯法就处以极刑，蒙冤家庭不敢上诉。", "citation": "《旧五代史》卷107·史弘肇传·刑杀与军狱，段落 jiu-wudaishi-205deb4a7860-p002555；已核上下文及传主，纸本及异文待核。", "note": "原文：然而不問罪之輕重，理之所在，但雲有犯，便處極刑，枉濫之家，莫敢上訴。；核对说明：两书都记滥刑，不由此认定具体死者所涉罪名属实。", "status": "draft", "id": "d4b0e577-fef8-5166-af53-27a8295c3fde", "subject_id": "a4a43459-e1f4-54f7-bb2e-e101fbe00008", "source_id": "38061fa7-243a-5f22-8624-a0d83925de8f"}, {"subject_table": "event", "field_path": "description", "claim_text": "葛延遇隐瞒经营所得，李屿鞭打并催索欠款。", "citation": "卷288·乾祐元年（948年十一月至十二月及追述）·zztj-v288-y0948-p059·原文件第65行", "note": "原文：李屿仆夫葛延遇，为屿贩鬻，多所欺匿，屿抶之，督其负甚急，；核对说明：经营欺匿、受罚和追债是告变背景，欠款金额未载。", "status": "draft", "id": "beed7413-7f5f-5687-b672-7b7d75c79e4a", "subject_id": "05132f16-48d1-57f9-9813-5c95260237e6", "source_id": "15490a22-9491-51f1-a3bd-8b639ffc682c"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "948年十一月李崧案发生前，经营及追债具体年月未载", "citation": "卷288·乾祐元年（948年十一月至十二月及追述）·zztj-v288-y0948-p059·原文件第65行", "note": "原文：李屿仆夫葛延遇，为屿贩鬻，多所欺匿，屿抶之，督其负甚急，；核对说明：按《资治通鉴》及对应补证纪时；追叙或他书记载另作说明，不自行换算公历日期。", "status": "draft", "id": "cd1aebf9-edd1-5526-b2bb-eceed9600bdb", "subject_id": "05132f16-48d1-57f9-9813-5c95260237e6", "source_id": "15490a22-9491-51f1-a3bd-8b639ffc682c"}, {"subject_table": "person", "field_path": "description", "claim_text": "葛延遇：替李屿贩卖经营，多次隐瞒所得。", "citation": "卷288·乾祐元年（948年十一月至十二月及追述）·zztj-v288-y0948-p059·原文件第65行", "note": "原文：李屿仆夫葛延遇，为屿贩鬻，多所欺匿，屿抶之，督其负甚急，；核对说明：核对同名、职务及行动后识别主体；展示简体，摘录保留原字。", "status": "draft", "id": "4b580da0-ddb4-598c-9cd4-379187d035e7", "subject_id": "811202de-9a8a-5ae0-b002-11da91b78d08", "source_id": "15490a22-9491-51f1-a3bd-8b639ffc682c"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "葛延遇：替李屿贩卖经营，多次隐瞒所得。", "citation": "卷288·乾祐元年（948年十一月至十二月及追述）·zztj-v288-y0948-p059·原文件第65行", "note": "原文：李屿仆夫葛延遇，为屿贩鬻，多所欺匿，屿抶之，督其负甚急，；核对说明：参与身份依据本句；人名沿用已有主体，原文不改字。", "status": "draft", "id": "d7f66680-a64d-569f-ae93-b2b3e8eaef4c", "subject_id": "ea7459b5-8e15-5207-b2e4-f18b37e910c3", "source_id": "15490a22-9491-51f1-a3bd-8b639ffc682c"}, {"subject_table": "person", "field_path": "description", "claim_text": "李屿：鞭打葛延遇，急催所欠款项。", "citation": "卷288·乾祐元年（948年十一月至十二月及追述）·zztj-v288-y0948-p059·原文件第65行", "note": "原文：李屿仆夫葛延遇，为屿贩鬻，多所欺匿，屿抶之，督其负甚急，；核对说明：核对同名、职务及行动后识别主体；展示简体，摘录保留原字。", "status": "draft", "id": "42588559-6db2-5a8d-8448-12911d2eac67", "subject_id": "3c5f9b7a-188d-5885-adb8-894048d9374b", "source_id": "15490a22-9491-51f1-a3bd-8b639ffc682c"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "李屿：鞭打葛延遇，急催所欠款项。", "citation": "卷288·乾祐元年（948年十一月至十二月及追述）·zztj-v288-y0948-p059·原文件第65行", "note": "原文：李屿仆夫葛延遇，为屿贩鬻，多所欺匿，屿抶之，督其负甚急，；核对说明：参与身份依据本句；人名沿用已有主体，原文不改字。", "status": "draft", "id": "4cec08f1-d19b-589c-9669-225b91e533b1", "subject_id": "b96b6a0b-010a-56a0-bda7-991f0915b152", "source_id": "15490a22-9491-51f1-a3bd-8b639ffc682c"}, {"subject_table": "event", "field_path": "description", "claim_text": "《旧五代史》记葛延遇拖欠李屿船佣，受到鞭打和催索。", "citation": "《旧五代史》卷一百〇八，段落 jiu-wudaishi-205deb4a7860-p002588；EPUB电子本，纸本及异文待核", "note": "原文：有部曲葛延遇者，逋李嶼船傭，嶼撻之，督其所負，；核对说明：船佣为该书补充，不能把《通鉴》经营欺匿概括为已经给出某项船租契约。", "status": "draft", "id": "f94cc199-fbff-56e6-97b9-5ab8102849d3", "subject_id": "05132f16-48d1-57f9-9813-5c95260237e6", "source_id": "5b02a7fc-c9dd-5907-8cfc-e1c81f8d9a36"}, {"subject_table": "event", "field_path": "description", "claim_text": "葛延遇与李澄合谋告发李屿谋反。", "citation": "卷288·乾祐元年（948年十一月至十二月及追述）·zztj-v288-y0948-p059·原文件第65行", "note": "原文：延遇与苏逢吉之仆李澄谋上变告屿谋反。；核对说明：这是告发行为，不是真实谋反事件；后文明确记李屿自诬及李氏蒙冤。", "status": "draft", "id": "e8114f83-967c-541b-bed6-b4668e856f9c", "subject_id": "0f2ae163-3ddd-534a-bf77-af4cd703c3f0", "source_id": "15490a22-9491-51f1-a3bd-8b639ffc682c"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "948年十一月甲寅诛杀前，具体告发日未载", "citation": "卷288·乾祐元年（948年十一月至十二月及追述）·zztj-v288-y0948-p059·原文件第65行", "note": "原文：延遇与苏逢吉之仆李澄谋上变告屿谋反。；核对说明：按《资治通鉴》及对应补证纪时；追叙或他书记载另作说明，不自行换算公历日期。", "status": "draft", "id": "d57d9b36-bdae-55b2-a93f-99d23c1f6de4", "subject_id": "0f2ae163-3ddd-534a-bf77-af4cd703c3f0", "source_id": "15490a22-9491-51f1-a3bd-8b639ffc682c"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "葛延遇：与李澄合谋告变。", "citation": "卷288·乾祐元年（948年十一月至十二月及追述）·zztj-v288-y0948-p059·原文件第65行", "note": "原文：延遇与苏逢吉之仆李澄谋上变告屿谋反。；核对说明：参与身份依据本句；人名沿用已有主体，原文不改字。", "status": "draft", "id": "6a16c788-02b7-51a4-b088-6cfab61c9db2", "subject_id": "f25c334f-2ece-5a8