aft", "id": "201b66c0-a84c-56fc-a836-f3c16b75cceb", "subject_id": "9df509c0-8b83-58f9-8b58-c1a3572a6c05", "source_id": "344f2a55-f39d-53b3-b041-6bf44314b17a"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "杨乙：受命征收归德军府收入。", "citation": "卷288·乾祐元年（948年十一月至十二月及追述）·zztj-v288-y0948-p061·原文件第67行", "note": "原文：弘肇领归德节度使，委亲吏杨乙收属府公利。；核对说明：参与身份依据本句；人名沿用已有主体，原文不改字。", "status": "draft", "id": "04122552-cbfe-5aa6-9693-8ad6fdaefbdd", "subject_id": "032d1689-a12d-5903-afb0-52db9cb428f1", "source_id": "344f2a55-f39d-53b3-b041-6bf44314b17a"}, {"subject_table": "event", "field_path": "description", "claim_text": "杨乙仗势骄横，归德官员和民众畏惧他。", "citation": "卷288·乾祐元年（948年十一月至十二月及追述）·zztj-v288-y0948-p061·原文件第67行", "note": "原文：乙依势骄横，合境畏之如弘肇，副使以下，望风展敬，乙皆下视之。；核对说明：副使以下的畏惧不转成自愿臣服或民众支持。", "status": "draft", "id": "6b57d788-3ebe-58f3-9f7b-d2c3afe8c36e", "subject_id": "d250f921-a5aa-579d-b6bd-0ef3dc33ec59", "source_id": "344f2a55-f39d-53b3-b041-6bf44314b17a"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "杨乙受命征收归德军府收入期间，具体年月未载", "citation": "卷288·乾祐元年（948年十一月至十二月及追述）·zztj-v288-y0948-p061·原文件第67行", "note": "原文：乙依势骄横，合境畏之如弘肇，副使以下，望风展敬，乙皆下视之。；核对说明：按《资治通鉴》及对应补证纪时；追叙或他书记载另作说明，不自行换算公历日期。", "status": "draft", "id": "3d475318-b715-5ab1-92f0-b51568930e48", "subject_id": "d250f921-a5aa-579d-b6bd-0ef3dc33ec59", "source_id": "344f2a55-f39d-53b3-b041-6bf44314b17a"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "杨乙：仗史弘肇的权势轻视当地官员，令官民畏惧。", "citation": "卷288·乾祐元年（948年十一月至十二月及追述）·zztj-v288-y0948-p061·原文件第67行", "note": "原文：乙依势骄横，合境畏之如弘肇，副使以下，望风展敬，乙皆下视之。；核对说明：参与身份依据本句；人名沿用已有主体，原文不改字。", "status": "draft", "id": "390bb6a2-5fd7-5ca3-9d27-2bf6ecd4b561", "subject_id": "5268ad79-bcf5-5c0d-b63c-ca8f3a699be4", "source_id": "344f2a55-f39d-53b3-b041-6bf44314b17a"}, {"subject_table": "event", "field_path": "description", "claim_text": "杨乙每月征钱一万缗交给史弘肇，民众不堪负担。", "citation": "卷288·乾祐元年（948年十一月至十二月及追述）·zztj-v288-y0948-p061·原文件第67行", "note": "原文：月率钱万缗以输弘肇，部民不胜其苦。