", "id": "3849da9c-4688-5bfe-b357-974237794cb6", "subject_id": "39b8a9b6-456f-5c74-b78e-22e586025977", "source_id": "702ba836-b926-5077-b82e-129f6105f39a"}, {"subject_table": "event", "field_path": "description", "claim_text": "侦骑请求攻击涧北后汉兵，李金全禁止越涧。", "citation": "卷288·乾祐元年（948年十一月至十二月及追述）·zztj-v288-y0948-p063·原文件第69行", "note": "原文：金全与诸将方会食，候骑白有汉兵数百在涧北，皆羸弱，请掩之。金全令曰：“敢言过涧者斩！”；核对说明：数百羸弱后汉兵是侦骑所报；拒绝攻击尚不是已打胜仗。涧名和侦骑姓名未载。", "status": "draft", "id": "e83dbc09-3f5b-54f2-9fb5-4c312bca297c", "subject_id": "4a9dd07c-3c8f-5fae-a05d-885bf7ba8297", "source_id": "344f2a55-f39d-53b3-b041-6bf44314b17a"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "948年十一月丙寅退兵之前，具体日未载", "citation": "卷288·乾祐元年（948年十一月至十二月及追述）·zztj-v288-y0948-p063·原文件第69行", "note": "原文：金全与诸将方会食，候骑白有汉兵数百在涧北，皆羸弱，请掩之。金全令曰：“敢言过涧者斩！”；核对说明：按《资治通鉴》及对应补证纪时；追叙或他书记载另作说明，不自行换算公历日期。", "status": "draft", "id": "afdac676-bf8a-53ee-a1c6-eb9575d0dd53", "subject_id": "4a9dd07c-3c8f-5fae-a05d-885bf7ba8297", "source_id": "344f2a55-f39d-53b3-b041-6bf44314b17a"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "李金全：拒绝侦骑攻击涧北汉兵的建议，禁止越涧。", "citation": "卷288·乾祐元年（948年十一月至十二月及追述）·zztj-v288-y0948-p063·原文件第69行", "note": "原文：金全与诸将方会食，候骑白有汉兵数百在涧北，皆羸弱，请掩之。金全令曰：“敢言过涧者斩！”；核对说明：参与身份依据本句；人名沿用已有主体，原文不改字。", "status": "draft", "id": "cc6ce556-1d45-5299-8de4-1504e6988a27", "subject_id": "f3424bad-0916-5eea-8956-12a83dee77e6", "source_id": "344f2a55-f39d-53b3-b041-6bf44314b17a"}, {"subject_table": "event", "field_path": "description", "claim_text": "入夜伏兵四起，李金全提醒诸将贸然进攻的危险。", "citation": "卷288·乾祐元年（948年十一月至十二月及追述）·zztj-v288-y0948-p063·原文件第69行", "note": "原文：及暮，伏兵四起，金鼓闻十馀里，金全令曰：“曏可与之战乎？”；核对说明：金鼓是军事声响，不说成南唐军遭全歼；伏兵将领未具名，不添加郭威等人。", "status": "draft", "id": "c339a72d-0c1a-5aa8-85cb-9dd3ccc7d10f", "subject_id": "c8f2135f-a2ba-51b5-b7dc-ecabaf086a19", "source_id": "344f2a55-f39d-53b3-b041-6bf44314b17a"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "948年十一月丙寅退兵前同日傍晚，具体日未载", "citation": "卷288·乾祐元年（948年十一月至十二月及追述）·zztj-v288-y0948-p063·原文件第69行", "note": "原文：及暮，伏兵四起，金鼓闻十馀里，金全令曰：“曏可与之战乎？”；核对说明：按《资治通鉴》及对应补证纪时；追叙或他书记载另作说明，不自行换算公历日期。", "status": "draft", "id": "e31f4f9d-7a05-5948-9dcc-b2dcdabdcfba", "subject_id": "c8f2135f-a2ba-51b5-b7dc-ecabaf086a19", "source_id": "344f2a55-f39d-53b3-b041-6bf44314b17a"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "李金全：听到伏兵发动后，反问此前是否能贸然交战。", "citation": "卷288·乾祐元年（948年十一月至十二月及追述）·zztj-v288-y0948-p063·原文件第69行", "note": "原文：及暮，伏兵四起，金鼓闻十馀里，金全令曰：“曏可与之战乎？”；核对说明：参与身份依据本句；人名沿用已有主体，原文不改字。", "status": "draft", "id": "89059aea-3190-5db2-8f23-120e9c39ee3b", "subject_id": "b9adbba4-eab3-5b1e-81fb-5af4bccd35c5", "source_id": "344f2a55-f39d-53b3-b041-6bf44314b17a"}, {"subject_table": "event", "field_path": "description", "claim_text": "《资治通鉴》记南唐士卒厌战、缺乏斗志，河中又太远，难以救援。十一月丙寅，南唐军退保海州。", "citation": "卷288·乾祐元年（948年十一月至十二月及追述）·zztj-v288-y0948-p063·原文件第69行", "note": "原文：时唐士卒厌兵，莫有斗志，又河中道远，势不相及。丙寅，唐兵退保海州。；核对说明：记录士气和距离为《资治通鉴》记载；当前河中仍在围困中，不能把后续949年李守贞败亡倒填为此次退军原因。与《新五代史》闻守贞已败才撤军的记载分别保留。", "status": "draft", "id": "91d36e54-6b46-5f32-a5d2-d11686db7779", "subject_id": "e4126114-f66d-53a9-8ca2-2eec825270e8", "source_id": "344f2a55-f39d-53b3-b041-6bf44314b17a"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "948年十一月丙寅", "citation": "卷288·乾祐元年（948年十一月至十二月及追述）·zztj-v288-y0948-p063·原文件第69行", "note": "原文：时唐士卒厌兵，莫有斗志，又河中道远，势不相及。丙寅，唐兵退保海州。；核对说明：按《资治通鉴》及对应补证纪时；追叙或他书记载另作说明，不自行换算公历日期。", "status": "draft", "id": "0f12d985-c85d-526a-88d6-48bf02852c7f", "subject_id": "e4126114-f66d-53a9-8ca2-2eec825270e8", "source_id": "344f2a55-f39d-53b3-b041-6bf44314b17a"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "李金全：所领南唐军退保海州。", "citation": "卷288·乾祐元年（948年十一月至十二月及追述）·zztj-v288-y0948-p063·原文件第69行", "note": "原文：时唐士卒厌兵，莫有斗志，又河中道远，势不相及。丙寅，唐兵退保海州。；核对说明：参与身份依据本句；人名沿用已有主体，原文不改字。", "status": "draft", "id": "3c45ed0d-3bbf-5fb5-a3b0-73b50edf2063", "subject_id": "f7fe9146-61eb-5641-8fae-2afd96d70542", "source_id": "344f2a55-f39d-53b3-b041-6bf44314b17a"}, {"subject_table": "event", "field_path": "description", "claim_text": "《新五代史》记南唐军攻沭阳，听说李守贞已经失败后撤回。", "citation": "《新五代史》卷62·南唐世家·援救李守贞，段落 xin-wudaishi-b08f244b9241-p003144；已核上下文及传主，纸本及异文待核。", "note": "原文：兵攻沭陽，聞守貞已敗，乃還。；核对说明：该书撤军原因与《通鉴》948年十一月因厌战、路远退军的记载不同；李守贞最终败亡在后续949年，不能用这一概述把《资治通鉴》当前退军改定949年。", "status": "draft", "id": "d24ffe89-3925-5751-88b4-fe659838cdce", "subject_id": "e4126114-f66d-53a9-8ca2-2eec825270e8", "source_id": "702ba836-b926-5077-b82e-129f6105f39a"}, {"subject_table": "event", "field_path": "description", "claim_text": "《旧五代史》十二月条记兖州奏报南唐军曾在沂州境筑寨，前月十七日退回海州，为李守贞牵制后汉军。", "citation": "《旧五代史》卷101·隐帝本纪·乾祐元年十二月，段落 jiu-wudaishi-205deb4a7860-p002462；已核上下文及传主，纸本及异文待核。", "note": "原文：兗州奏，淮賊先於沂州界立柵，前月十七日已歸海州，為李守貞牽制也。；核对说明：前月按十二月上下文为十一月；这是十二月奏报，不把撤军写成十二月发生。贬称按原文保留，不用于本站主体名称。", "status": "draft", "id": "00ff74cd-c258-54d7-91c0-cc3068a0c66a", "subject_id": "e4126114-f66d-53a9-8ca2-2eec825270e8", "source_id": "931e2b3e-52d4-50a6-b465-da07f4acc580"}, {"subject_table": "event", "field_path": "description", "claim_text": "李璟致书后汉请恢复商旅往来、赦免李守贞，未获答复。", "citation": "卷288·乾祐元年（948年十一月至十二月及追述）·zztj-v288-y0948-p063·原文件第69行", "note": "原文：唐主遗帝书谢，请复通商旅，且请赦守贞，朝廷不报。；核对说明：不报是未答复，不说成已经恢复贸易、批准赦免或拒绝使者入境。", "status": "draft", "id": "244a5a07-6a83-57d5-9ba3-3bac6d4dc336", "subject_id": "13667fa9-8a07-50e2-8606-ddaf48411b73", "source_id": "344f2a55-f39d-53b3-b041-6bf44314b17a"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "948年十一月南唐退兵后，送信及接收具体日未载", "citation": "卷288·乾祐元年（948年十一月至十二月及追述）·zztj-v288-y0948-p063·原文件第69行", "note": "原文：唐主遗帝书谢，请复通商旅，且请赦守贞，朝廷不报。；核对说明：按《资治通鉴》及对应补证纪时；追叙或他书记载另作说明，不自行换算公历日期。", "status": "draft", "id": "34f5ac79-e69b-5866-984f-0487d8a39c72", "subject_id": "13667fa9-8a07-50e2-8606-ddaf48411b73", "source_id": "344f2a55-f39d-53b3-b041-6bf44314b17a"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "李璟：送信致歉，请求恢复商旅往来并赦免李守贞。", "citation": "卷288·乾祐元年（948年十一月至十二月及追述）·zztj-v288-y0948-p063·原文件第69行", "note": "原文：唐主遗帝书谢，请复通商旅，且请赦守贞，朝廷不报。；核对说明：参与身份依据本句；人名沿用已有主体，原文不改字。", "status": "draft", "id": "f474fa0d-6833-5840-810b-e21181c4f417", "subject_id": "6b1d0b89-f586-55c7-b9dd-85a6c812f4cc", "source_id": "344f2a55-f39d-53b3-b041-6bf44314b17a"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "刘承祐：其朝廷收到南唐请求后没有答复。", "citation": "卷288·乾祐元年（948年十一月至十二月及追述）·zztj-v288-y0948-p063·原文件第69行", "note": "原文：唐主遗帝书谢，请复通商旅，且请赦守贞，朝廷不报。；核对说明：参与身份依据本句；人名沿用已有主体，原文不改字。", "status": "draft", "id": "19359e5b-0492-5b4c-9604-9ac3ec4d618e", "subject_id": "cb3101e5-310d-5007-a537-55efceba49a5", "source_id": "344f2a55-f39d-53b3-b041-6bf44314b17a"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "李守贞：成为请求赦免的对象。", "citation": "卷288·乾祐元年（948年十一月至十二月及追述）·zztj-v288-y0948-p063·原文件第69行", "note": "原文：唐主遗帝书谢，请复通商旅，且请赦守贞，朝廷不报。；核对说明：参与身份依据本句；人名沿用已有主体，原文不改字。", "status": "draft", "id": "099b4b7c-c829-5f60-a483-c9141ea7c114", "subject_id": "5e247090-1abd-5c3c-9219-7bc0604b1c6d", "source_id": "344f2a55-f39d-53b3-b041-6bf44314b17a"}, {"subject_table": "event", "field_path": "description", "claim_text": "《旧五代史》十二月条保留李璟书信，称因李守贞求援及沿淮屯兵而戒备，请恢复商旅往来，后汉未答复。", "citation": "《旧五代史》卷101·隐帝本纪·乾祐元年十二月，段落 jiu-wudaishi-205deb4a7860-p002462；已核上下文及传主，纸本及异文待核。", "note": "原文：淮南偽主李璟奉書於帝，云：「先因河府李守貞求援，又聞大國沿淮屯軍，當國亦於境上防備。昨聞大朝收軍，當國尋已徹備，其商旅請依舊日通行。」朝廷不報。；核对说明：这是李璟在信中的解释，不直接认定后汉确已全面收兵；所引信文未写请赦李守贞，不能由该书独立印证这一请求。", "status": "draft", "id": "0b74b2ba-3b22-51ef-afd0-3b40114e7afb", "subject_id": "13667fa9-8a07-50e2-8606-ddaf48411b73", "source_id": "931e2b3e-52d4-50a6-b465-da07f4acc580"}, {"subject_table": "event", "field_path": "description", "claim_text": "刘知远葬于睿陵，庙号高祖。", "citation": "卷288·乾祐元年（948年十一月至十二月及追述）·zztj-v288-y0948-p064·原文件第70行", "note": "原文：壬申，葬睿文圣武昭肃孝皇帝于睿陵，庙号高祖。；核对说明：葬礼与此前死亡分开，睿文圣武昭肃孝皇帝为刘知远的身后称号；不重新记一次死亡。", "status": "draft", "id": "f0435d70-e488-56df-ac09-96aca26ac906", "subject_id": "70c735ac-5cd2-5ef9-b2d4-9116b7c74fcd", "source_id": "344f2a55-f39d-53b3-b041-6bf44314b17a